choose.otherwise:
(o.issuer_unit_id = #{unitId}
 OR EXISTS (SELECT 1 FROM task_branch b JOIN task_assignment a ON a.branch_id = b.id
             WHERE b.task_id = o.id AND a.to_unit_id = #{unitId})
 OR EXISTS (SELECT 1 FROM task_branch b JOIN task_transfer_request t ON t.branch_id = b.id
             WHERE b.task_id = o.id AND t.target_unit_id = #{unitId}
               AND t.status IN ('AWAITING_TARGET', 'AWAITING_ISSUER')))

mapper.select:
SELECT id AS id, actor_unit_id AS actorUnitId, action_code AS actionCode,
       idempotency_key AS idempotencyKey, request_digest AS requestDigest,
       task_id AS taskId, branch_id AS branchId, created_at AS createdAt
  FROM task_command WHERE actor_unit_id = #{unitId} AND action_code = #{action}
    AND idempotency_key = #{key}

mapper.update:
UPDATE task_branch SET current_assignment_id = #{assignmentId}, version = version + 1
 WHERE id = #{branchId}
   AND current_assignment_id IS NULL
               current_assignment_id = #{expectedId}
   AND status = 'OPEN'

UPDATE task_assignment SET status = 'IN_PROGRESS', accepted_by_user_id = #{userId},
    accepted_at = #{at}, version = version + 1
 WHERE id = #{id} AND status = 'PENDING_ACCEPT' AND version = #{version}

UPDATE task_assignment SET status = #{newStatus}, ended_by_user_id = #{userId},
    ended_at = #{at}, end_reason = #{reason,jdbcType=VARCHAR}, version = version + 1
 WHERE id = #{id} AND status = #{expectedStatus} AND version = #{version}

UPDATE task_order SET current_due_at = #{newDue}, updated_at = CURRENT_TIMESTAMP(6),
    version = version + 1
 WHERE id = #{id} AND status = 'OPEN' AND current_due_at = #{oldDue}

UPDATE task_transfer_request SET status = 'WITHDRAWN', version = version + 1
 WHERE id = #{id} AND version = #{version}
   AND status IN ('AWAITING_TARGET', 'AWAITING_ISSUER')

UPDATE task_command SET task_id = #{taskId}, branch_id = #{branchId,jdbcType=BIGINT}
 WHERE actor_unit_id = #{unitId} AND action_code = #{action}
   AND idempotency_key = #{key} AND task_id IS NULL
